const __pageData = JSON.parse('{"title":"Tulsi Gabbard","description":"","frontmatter":{"title":"Tulsi Gabbard","created":"2026-08-06T00:00:00.000Z","updated":"2026-08-06T00:00:00.000Z","type":"entity","tags":["syria","congress","intelligence","media-narrative"],"sources":["raw/assad-day-in-damascus.md","raw/badlands-brief-05f.md","raw/badlands-brief-1cd.md","raw/badlands-brief-2c5.md","raw/badlands-brief-314.md","raw/badlands-brief-707.md","raw/badlands-brief-6f4.md","raw/badlands-brief-6f0.md","raw/badlands-brief-708.md","raw/badlands-brief-70c.md","raw/badlands-brief-835.md","raw/badlands-brief-949.md","raw/badlands-brief-9ac.md","raw/badlands-brief-990.md","raw/badlands-brief-a89.md","raw/badlands-brief-ac2.md","raw/badlands-brief-d3b.md","raw/badlands-brief-da2.md","raw/badlands-brief-e15.md","raw/badlands-brief-f87.md","raw/badlands-news-brief-017.md","raw/badlands-news-brief-030.md","raw/badlands-news-brief-071.md","raw/badlands-news-brief-144.md","raw/badlands-news-brief-2d5.md","raw/badlands-news-brief-3ab.md","raw/badlands-news-brief-4a9.md","raw/badlands-news-brief-520.md","raw/badlands-news-brief-58e.md","raw/badlands-news-brief-5a3.md","raw/badlands-news-brief-721.md","raw/badlands-news-brief-795.md"],"confidence":"medium"},"headers":[],"relativePath":"entities/tulsi-gabbard.md","filePath":"entities/tulsi-gabbard.md","lastUpdated":null}');
